initialize:
// ============================================================
//  MadridMove – zentrale Konfiguration
//  Alle externen APIs und alle Schwellwerte stehen NUR hier.
//  Jeder Wert kann per Umgebungsvariable überschrieben werden,
//  z. B. ORS_API_KEY=abc node-red   bzw.   docker run -e ORS_API_KEY=abc ...
// ============================================================
const cfg = {
    // Topic-Präfix: wird von configure.py gesetzt, nicht von Hand ändern
    prefix: 'upm-dsiot-g6/move',

    apis: {
        // BiciMAD (GBFS-Einstiegsdatei; die Feed-URLs werden daraus gelesen)
        gbfs: env.get('GBFS_URL') || 'https://madrid.publicbikesystem.net/customer/gbfs/v2/gbfs.json',
        // Open-Meteo (Wetter, ohne Schlüssel)
        meteo: env.get('METEO_URL') || 'https://api.open-meteo.com/v1/forecast',
        // openrouteservice (Routing mit Höhe und Wegart, kostenloser Schlüssel)
        ors: env.get('ORS_URL') || 'https://api.openrouteservice.org',
        orsKey: env.get('ORS_API_KEY') || '',
        // Geocoding (Adresse -> Koordinaten): Nominatim / OpenStreetMap, ohne Schlüssel.
        // Nutzungsregeln: max. 1 Anfrage pro Sekunde, Anwendung im User-Agent nennen,
        // KEINE Suche bei jedem Tastendruck (deshalb Suche nur auf Knopfdruck).
        geocode: env.get('GEOCODE_URL') || 'https://nominatim.openstreetmap.org/search',
        geocodeUserAgent: 'MadridMove/1.0 (UPM DSIoT student project)'
    },

    // Suchgebiet für Adressen: Stadt Madrid (links, oben, rechts, unten)
    cityViewbox: '-3.89,40.57,-3.52,40.31',

    // Wetterpunkt: Puerta del Sol
    weatherPoint: { lat: 40.4168, lon: -3.7038 },

    // Parameter der Empfehlungslogik (Minuten, km/h, mm, °C)
    reco: {
        bikeMinBikes: 1,        // weniger Räder am Start -> BiciMAD nicht möglich
        bikeOkBikes: 3,         // weniger als das (aber >= bikeMinBikes) -> "knapp"
        knappPenalty: 3,        // Aufschlag bei "knapp": evtl. ist das Rad weg, bis man da ist
        bikeMinDocks: 1,        // weniger freie Plätze am Ziel -> nur HINWEIS (Rad kann mit
                                // Schloss neben der Station abgestellt werden), kein Ausschluss
        dockMin: 2,             // Ausleihen + Abstellen
        minPerHmUp: 0.05,       // Aufschlag pro Höhenmeter bergauf (3 s; BiciMAD-Räder sind E-Bikes)
        cyclewayBonusMax: 3,    // Bonus bei 100 % Radweg
        rainLight: 0.1,         // mm Niederschlag (letzte 15 min) = leichter Regen
        rainHeavy: 1.0,         // mm = starker Regen
        rainPenaltyBike: 8,
        rainPenaltyWalk: 5,
        windStrong: 30,         // km/h
        windPenaltyBike: 3,
        coldBelow: 3,           // °C
        hotAbove: 35,           // °C
        tempPenalty: 3,
        bikeSpeedKmh: 14,       // nur Schätzmodus (ohne ORS)
        walkSpeedKmh: 4.8,      // nur Schätzmodus
        detourFactor: 1.3,      // Luftlinie -> Straßenweg (Schätzmodus, Fußwege zur Station)
        maxWalkToStationM: 1000,// weiter als das bis zur nächsten Station -> BiciMAD nicht sinnvoll
        transitSpeedKmh: 18,    // ÖPNV-Schätzung: mittlere Reisegeschwindigkeit
        transitAccessMin: 8,    // Fußwege zur und von der Haltestelle
        transitWaitMin: 4,      // mittlere Wartezeit
        staleMin: 15,           // BiciMAD-Daten älter als das = veraltet
        weatherStaleMin: 30,    // Wetterdaten älter als das = veraltet
        maxRoutesPerUser: 3,

        // Zeitfenster und Meldungen
        windowMin: 30,          // so viele Minuten vor der Abfahrt ist eine Route "aktiv"
        preInfoMin: 15,         // Vorab-Info so viele Minuten vor der Abfahrt
        switchMinGain: 2        // Empfehlung wechselt nur bei mind. so viel Minuten Vorteil
                                // (außer die bisherige Option ist gar nicht mehr möglich)
    },

    // Feste Orte für die Auswahl im Formular (werden retained auf .../static/places
    // veröffentlicht). Koordinaten auf ca. 100 m genau, zum Eintragen eigener Orte
    // z. B. in OpenStreetMap rechtsklicken -> "Adresse anzeigen".
    places: [
        // Hochschulen
        { id: 'etsisi', cat: 'Uni', label: 'UPM ETSISI (Campus Sur)', lat: 40.3897, lon: -3.6280 },
        { id: 'ciudad-uni', cat: 'Uni', label: 'Ciudad Universitaria', lat: 40.4437, lon: -3.7276 },
        { id: 'etsit', cat: 'Uni', label: 'UPM ETSIT (Ciudad Universitaria)', lat: 40.4525, lon: -3.7266 },
        { id: 'uc3m-toledo', cat: 'Uni', label: 'UC3M Puerta de Toledo', lat: 40.4072, lon: -3.7110 },
        { id: 'ie', cat: 'Uni', label: 'IE University (María de Molina)', lat: 40.4371, lon: -3.6866 },
        // Bahnhöfe und Umsteigepunkte
        { id: 'atocha', cat: 'Bahnhof', label: 'Estación de Atocha', lat: 40.4066, lon: -3.6892 },
        { id: 'chamartin', cat: 'Bahnhof', label: 'Estación de Chamartín', lat: 40.4722, lon: -3.6826 },
        { id: 'nuevos-ministerios', cat: 'Bahnhof', label: 'Nuevos Ministerios', lat: 40.4463, lon: -3.6918 },
        { id: 'moncloa', cat: 'Bahnhof', label: 'Moncloa (Intercambiador)', lat: 40.4352, lon: -3.7190 },
        { id: 'principe-pio', cat: 'Bahnhof', label: 'Príncipe Pío', lat: 40.4210, lon: -3.7208 },
        { id: 'plaza-castilla', cat: 'Bahnhof', label: 'Plaza de Castilla', lat: 40.4669, lon: -3.6889 },
        { id: 'avenida-america', cat: 'Bahnhof', label: 'Avenida de América', lat: 40.4381, lon: -3.6770 },
        { id: 'mendez-alvaro', cat: 'Bahnhof', label: 'Méndez Álvaro (Estación Sur)', lat: 40.3953, lon: -3.6787 },
        // Zentrum und bekannte Orte
        { id: 'sol', cat: 'Zentrum', label: 'Puerta del Sol', lat: 40.4169, lon: -3.7035 },
        { id: 'plaza-mayor', cat: 'Zentrum', label: 'Plaza Mayor', lat: 40.4155, lon: -3.7074 },
        { id: 'callao', cat: 'Zentrum', label: 'Callao (Gran Vía)', lat: 40.4200, lon: -3.7058 },
        { id: 'plaza-espana', cat: 'Zentrum', label: 'Plaza de España', lat: 40.4234, lon: -3.7122 },
        { id: 'palacio-real', cat: 'Zentrum', label: 'Palacio Real', lat: 40.4180, lon: -3.7143 },
        { id: 'cibeles', cat: 'Zentrum', label: 'Plaza de Cibeles', lat: 40.4193, lon: -3.6931 },
        { id: 'colon', cat: 'Zentrum', label: 'Plaza de Colón', lat: 40.4253, lon: -3.6903 },
        { id: 'prado', cat: 'Zentrum', label: 'Museo del Prado', lat: 40.4138, lon: -3.6921 },
        { id: 'retiro', cat: 'Zentrum', label: 'Retiro (Puerta de Alcalá)', lat: 40.4199, lon: -3.6887 },
        { id: 'malasana', cat: 'Zentrum', label: 'Malasaña (Plaza del Dos de Mayo)', lat: 40.4268, lon: -3.7038 },
        { id: 'lavapies', cat: 'Zentrum', label: 'Lavapiés', lat: 40.4089, lon: -3.7008 },
        { id: 'debod', cat: 'Zentrum', label: 'Templo de Debod', lat: 40.4240, lon: -3.7177 },
        { id: 'matadero', cat: 'Zentrum', label: 'Matadero Madrid', lat: 40.3920, lon: -3.6975 },
        { id: 'bernabeu', cat: 'Zentrum', label: 'Estadio Santiago Bernabéu', lat: 40.4531, lon: -3.6883 }
    ]
};
global.set('cfg', cfg);
node.status({
    fill: cfg.apis.orsKey ? 'green' : 'yellow', shape: 'dot',
    text: cfg.apis.orsKey ? 'ORS-Schlüssel gesetzt' : 'kein ORS-Schlüssel: Schätzmodus'
});

func:
// Feste Orte aus der Konfiguration -> .../static/places (retained, QoS 1).
// Wie die Stationsliste: statische Daten, die jeder neue Client sofort bekommt.
const cfg = global.get('cfg');
const places = (cfg.places || []).map(p => ({ id: p.id, cat: p.cat, label: p.label, lat: p.lat, lon: p.lon }));
node.status({ fill: 'green', shape: 'dot', text: places.length + ' Orte veröffentlicht' });
return { topic: cfg.prefix + '/static/places', payload: places, qos: 1, retain: true };
